fail = []
for old, new in PAIRS:
    if old not in t:
        fail.append(old[:70])
    else:
        t = t.replace(old, new, 1)

if fail:
    print("❌ 未命中：")
    for f in fail:
        print("   ", f)
    sys.exit(1)

open(P, "w", encoding="utf-8").write(t)
print(f"✅ 全部 {len(PAIRS)} 处替换成功")
